public class Main {static int[] findTopper(int[][] marks){if(marks==null||marks.length==0)throw new IllegalArgumentException();int bestRow=0,bestTotal=-1;for(int i=0;i<marks.length;i++){if(marks[i]==null||marks[i].length==0)throw new IllegalArgumentException();int total=0;for(int x:marks[i]){if(x<0||x>100)throw new IllegalArgumentException();total+=x;}if(total>bestTotal){bestTotal=total;bestRow=i;}}return new int[]{bestRow,bestTotal};}public static void main(String[]args){int[] r=findTopper(new int[][]{{78,85,90},{88,92,79},{65,70,95}});System.out.println("("+r[0]+", "+r[1]+")");System.out.println("Time: O(m*n), extra space: O(1)");}}